/**
 * Pixel-art assets: fighter sprite sheets, effects, stage layers and portraits.
 * The PNGs are generated by `npm run art` (see art/) and described by atlas.json.
 */

import atlasData from './atlas.json';

export interface AnimMeta {
  row: number;
  frames: number;
  fps: number;
  loop: boolean;
  /** Frames (inclusive) that show the strike; the sim's active window is spread over them. */
  strike?: [number, number];
}

export interface FighterAtlas {
  cell: [number, number];
  anchor: [number, number];
  anims: Record<string, AnimMeta>;
}

interface FxRow {
  row: number;
  frames: number;
  fps: number;
}

interface Atlas {
  fighters: Record<string, FighterAtlas>;
  portraits: { size: number; moods: string[]; order: string[] };
  fx: { cell: number; rows: Record<string, FxRow> };
  /** The story map: where the hero stands on each sombrero, the road between them, and the hat sprite size. */
  map: { nodes: { x: number; y: number }[]; road: [number, number][]; nodeAt: number[]; hat: { w: number; h: number } };
  /** Cells of hazards.png: the barrel's rolling frames and the anvil. */
  hazards: { barrel: { x: number; y: number; w: number; h: number; frames: number }; anvil: { x: number; y: number; w: number; h: number } };
}

export const ATLAS = atlasData as unknown as Atlas;

const urls = import.meta.glob('../assets/**/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;

/** Hashed URL of a generated PNG, e.g. url('sprites/bean.png'). */
export function url(path: string): string {
  const found = urls[`../assets/${path}`];
  if (!found) throw new Error(`missing asset ${path}`);
  return found;
}

export interface Assets {
  fighters: Record<string, HTMLImageElement>;
  fx: HTMLImageElement;
  stageBack: HTMLImageElement[];
  stageFg: HTMLImageElement[];
  pipWon: HTMLImageElement;
  pipEmpty: HTMLImageElement;
  petals: HTMLImageElement;
  portraits: HTMLImageElement;
  hazards: HTMLImageElement;
  map: { back: HTMLImageElement; hats: HTMLImageElement; icons: HTMLImageElement };
  /** White silhouettes of each sprite sheet, used for the hit flash. */
  flash: Record<string, HTMLCanvasElement>;
}

function load(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`could not load ${src}`));
    img.src = src;
  });
}

function silhouette(img: HTMLImageElement): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = img.width;
  c.height = img.height;
  const g = c.getContext('2d')!;
  g.drawImage(img, 0, 0);
  g.globalCompositeOperation = 'source-in';
  g.fillStyle = '#ffffff';
  g.fillRect(0, 0, c.width, c.height);
  return c;
}

let cached: Promise<Assets> | null = null;

/** Loads everything the canvas needs, once, along with the pixel font used for banners. */
export function loadAssets(): Promise<Assets> {
  cached ??= (async () => {
    const ids = Object.keys(ATLAS.fighters);
    const [fighterImgs, fx, backs, fgs, pipWon, pipEmpty, petals, portraits, hazards, mapBack, mapHats, mapIcons] = await Promise.all([
      Promise.all(ids.map((id) => load(url(`sprites/${id}.png`)))),
      load(url('sprites/fx.png')),
      Promise.all([1, 2, 3].map((n) => load(url(`stages/stage${n}-back.png`)))),
      Promise.all([1, 2, 3].map((n) => load(url(`stages/stage${n}-fg.png`)))),
      load(url('ui/pip-won.png')),
      load(url('ui/pip-empty.png')),
      load(url('ui/petals.png')),
      load(url('sprites/portraits.png')),
      load(url('sprites/hazards.png')),
      load(url('ui/map.png')),
      load(url('ui/map-hats.png')),
      load(url('ui/map-icons.png')),
      document.fonts.load('8px "Press Start 2P"'),
    ]);
    return {
      fighters: Object.fromEntries(ids.map((id, i) => [id, fighterImgs[i]])),
      fx,
      stageBack: backs,
      stageFg: fgs,
      pipWon,
      pipEmpty,
      petals,
      portraits,
      hazards,
      map: { back: mapBack, hats: mapHats, icons: mapIcons },
      flash: Object.fromEntries(ids.map((id, i) => [id, silhouette(fighterImgs[i])])),
    };
  })();
  // a failed load must not poison every later attempt
  cached.catch(() => {
    cached = null;
  });
  return cached;
}

/** CSS for a portrait of `charId` showing `mood`, scaled by an integer factor. */
export function portraitStyle(charId: string, mood: string, scale: number): Record<string, string | number> {
  const { size, moods, order } = ATLAS.portraits;
  const col = Math.max(0, moods.indexOf(mood));
  const row = Math.max(0, order.indexOf(charId));
  return {
    width: size * scale,
    height: size * scale,
    backgroundImage: `url(${url('sprites/portraits.png')})`,
    backgroundSize: `${moods.length * size * scale}px ${order.length * size * scale}px`,
    backgroundPosition: `-${col * size * scale}px -${row * size * scale}px`,
    imageRendering: 'pixelated',
  };
}
